sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var events = [];

    var gr = new GlideRecordSecure('x_2130921_caresy_0_patient_timeline');
    gr.orderByDesc('event_date');
    gr.query();

    while (gr.next()) {

        events.push({
            sys_id: gr.getUniqueValue(),

            timeline_number: gr.getValue('number'),

            patient_sys_id: gr.getValue('patient'),
            patient: gr.getDisplayValue('patient'),

            admission_sys_id: gr.getValue('admission'),
            admission: gr.getDisplayValue('admission'),

            event_type: gr.getDisplayValue('event_type'),
            event_date: gr.getValue('event_date'),

            event_title: gr.getValue('event_title'),
            description: gr.getValue('description'),

            status: gr.getDisplayValue('status'),

            active: gr.getValue('active') == '1'
        });
    }

    response.setStatus(200);

    response.setBody({
        success: true,
        count: events.length,
        patient_timeline_events: events
    });

})(request, response);
